/// Source and destination paths for a single copy operation.
pub(crate) struct CopyPaths<'a> {
    source: &'a Path,
    dest: &'a Path,
}

impl CopyPaths<'_> {
    fn operand_arg() -> Arg {
        Arg::new(options::PATHS)
            .action(ArgAction::Append)
            .value_hint(clap::ValueHint::AnyPath)
            .value_parser(ValueParser::os_string())
    }

    /// Copy the specified attributes from the source path to the destination path.
    pub(crate) fn copy_attributes(
        &self,
        attributes: &Attributes,
        dereference: bool,
    ) -> CopyResult<()> {
        fn handle_preserve<F: Fn() -> CopyResult<()>>(p: &Preserve, f: F) -> CopyResult<()> {
            match p {
                Preserve::No { .. } => {}
                Preserve::Yes { required } => {
                    let result = f();
                    if *required {
                        result?;
                    } else if let Err(error) = result {
                        show_error_if_needed(&error);
                    }
                }
            };
            Ok(())
        }

        let canonical_source;
        let source = if dereference {
            match canonicalize(self.source, MissingHandling::Normal, ResolveMode::Physical) {
                Ok(path) => {
                    canonical_source = path;
                    canonical_source.as_path()
                }
                Err(_) => return Ok(()),
            }
        } else {
            self.source
